import { useEffect, useState } from 'react';
import toast from 'react-hot-toast';
import axios from 'axios';

const useGetConversations = () => {
  const [loading,setloading] = useState(false);
  const [conversations, setConversations] = useState([]);

  useEffect(() => {
    const getConversation = async () => {
     setloading(true);
      try {
        
        const yourToken=getCookie("jtws");

        // const res =  fetch('https://chats-backend-sgl1.onrender.com/api/users', {
        //   method: 'GET',
        //   headers: {
        //     'Content-Type': 'application/json',
        //     'Authorization': `Bearer ${yourToken}`, // Include your token here
        //   },
        //   credentials: 'include', // Include credentials
        // })

        

        
        const res = await axios.get('https://chats-backend-sgl1.onrender.com/api/users', {
          headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${yourToken}`, // Include your token here
              },
          withCredentials: true // Include cookies with the request
        });

        const data =  res.data;

        console.log(data);
        if (data.error) {
          throw new Error(data.error);
        }
        setConversations(data);
      } catch (err) {
        toast.error(err.message);
      } finally {
       setloading(false);
      }
    };

    getConversation();
  }, []); // Ensure the dependency array is empty

  return { loading, conversations };
};

export default useGetConversations;

function getCookie(name) {
  const nameEQ = name + "=";
  const ca = document.cookie.split(';');
  for (let i = 0; i < ca.length; i++) {
    let c = ca[i];
    while (c.charAt(0) === ' ') c = c.substring(1, c.length);
    if (c.indexOf(nameEQ) === 0) return c.substring(nameEQ.length, c.length);
  }
  return null;
}




