import React, { useState } from 'react'
import {BsSend} from "react-icons/bs"
import {  Smile, X } from "lucide-react";
import useSendMessage from '../../hooks/useSendMessage';
import EmojiPicker from "emoji-picker-react";
const MessageInput = () => {
   const [message,setMessage]=useState("");
   const [showEmojiPicker, setShowEmojiPicker] = useState(false);
     const {loading,sendMessage}=useSendMessage();
     const handleSubmit=async(e)=>{
        e.preventDefault();
        console.log(message);
        if(!message) return;
        await sendMessage((message));
        setMessage("");
     }
     const onEmojiClick = (emojiObject) => {
      setMessage((prevText) => prevText + emojiObject.emoji);
    };
   
  return (
    <form className='px-4 my-3' onSubmit={handleSubmit}>

      <div className='flex flex-auto relative '>
      <div className="relative pr-2 ">
            <button
              type="button"
              className="btn btn-circle btn-sm  size-11"
              onClick={() => setShowEmojiPicker((prev) => !prev)}
            >
              <Smile size={25} />
            </button>
            {showEmojiPicker && (
              <div className="absolute bottom-full left-0 mb-2 z-10 bg-white border rounded-lg shadow-lg p-0">
                <div className="relative">
                  <button
                    onClick={() => setShowEmojiPicker(false)}
                    className="absolute -top-4 -right-4 w-6  h-6 rounded-full bg-red-500 text-white flex items-center justify-center"
                    type="button"
                  >
                    <X size={16} />
                  </button>
                  <div
                    className="custom-emoji-picker"
                    style={{
                      //width: "400px", // Adjust width
                      height: "450px", // Adjust height
                      overflow: "hidden", // Prevents overflow of content
                    }}
                  >
                    <EmojiPicker onEmojiClick={onEmojiClick} />
                  </div>
                  
                </div>
              </div>
            )}
          </div>
          <div className="w-full  relative">
      <input
					type='text'
					className='border text-sm rounded-lg block w-full p-2.5  bg-gray-700 border-gray-600 text-white'
					placeholder='     Send a message'
					value={message}
					onChange={(e) => setMessage(e.target.value)}
				/>
        <button type='submit'
         className='absolute inset-y-0 end-0 flex items-center pe-3'>
        { loading?<div className='loading loading-spinner'></div>:<BsSend/>} 
         </button>
      </div>
     </div>
    </form>
  )
}

export default MessageInput
